SELECT rentabilidad_7.deudor AS deudor,   rentabilidad_7.rutadeventa AS rutadeventa,   SUM(rentabilidad_7.rentabilidad) AS temp(calculation_5560818164729849)(3482281234)(0),   SUM(rentabilidad_7.cf) AS temp(calculation_5560818164729849)(3669921802)(0) FROM rentabilidad_7 WHERE ((rentabilidad_7.figura = 'Preventa On Premise') AND (rentabilidad_7.sedeforaneosintec = 'Sede') AND (rentabilidad_7.zona = 'OC')) GROUP BY rentabilidad_7.deudor,   rentabilidad_7.rutadeventa;
